const items = $input.all();
const evoUrl = "https://evolution.marcaopersonal.com";
const evoKey = "Marcao_Evo_Key_2026_Secure!";
const results = [];

for (const it of items) {
  const d = it.json;
  const tel = d.telefone;
  const baloes = d.baloes || (d.texto ? d.texto.split(/\n+/).filter(b => b.trim()) : []);

  // 1. Envio sequencial de cada balão com simulação de digitação
  for (let i = 0; i < baloes.length; i++) {
    const balao = baloes[i].trim();
    if (!balao) continue;

    // Simula digitando
    try {
      await this.helpers.httpRequest({
        method: 'POST',
        url: `${evoUrl}/chat/sendPresence/sofia`,
        headers: { 'apikey': evoKey, 'Content-Type': 'application/json' },
        body: { number: tel, presence: 'composing', delay: 2000 },
        json: true
      });
    } catch (e) {}

    await new Promise(r => setTimeout(r, 1500));

    // Envia o balão de texto
    try {
      const res = await this.helpers.httpRequest({
        method: 'POST',
        url: `${evoUrl}/message/sendText/sofia`,
        headers: { 'apikey': evoKey, 'Content-Type': 'application/json' },
        body: { number: tel, text: balao },
        json: true
      });
      results.push({ telefone: tel, indice: i, status: 'enviado', res });
    } catch (err) {
      results.push({ telefone: tel, indice: i, error: err.message });
    }

    if (i < baloes.length - 1) {
      await new Promise(r => setTimeout(r, 1200));
    }
  }
}

return [{ json: { success: true, totalEnviados: results.length, details: results } }];

